183	
184	    fn set_compiled(&mut self, compiled: Compiled) {
185	        self.compiled = Some(compiled);
186	        self.status = TaskStatus::Running;
187	    }
188	
189	    /// Folds a harness event into the task's output and status.
190	    fn apply(&mut self, event: HarnessEvent) {
191	        match self.reply.apply(event) {
192	            Some(error) => self.fail(error),
193	            None if self.reply.done && self.status == TaskStatus::Running => {
194	                self.status = TaskStatus::Done
195	            }
196	            None => {}
197	        }
198	    }
199	
200	    fn fail(&mut self, error: String) {
201	        self.reply.parts.push(ReplyPart::Error(error));
202	        self.status = TaskStatus::Failed;
203	    }
204	
205	    /// The run is over. One that ended without a result, as when the harness
206	    /// was stopped, failed, and nothing still running in it finished.
207	    fn end(&mut self) {
208	        if self.reply.done {
209	            return;
210	        }
211	        self.reply.done = true;
212	        self.reply.settle_tools(ToolState::Failed);
213	        if self.status != TaskStatus::Failed {
214	            self.fail("The harness stopped without a result.".into());
215	        }
216	    }
217	}
218	
219	/// A harness reply as it streams in.
220	#[derive(Default)]
221	pub(crate) struct Reply {
222	    parts: Vec<ReplyPart>,
223	    done: bool,
224	}
225	
226	enum ReplyPart {
227	    Text(String),
228	    Tool(ToolCall),
229	    Error(String),
230	}
231	
232	#[derive(Debug, PartialEq)]
233	struct ToolCall {
234	    id: String,
235	    name: String,
236	    summary: Option<String>,
237	    state: ToolState,
238	}
239	
240	impl ToolCall {
241	    /// The tool's name, for the output column. Left out when the badge already
242	    /// says what the tool is and there is a summary to show instead; a tool
243	    /// the badge only calls "Tool" keeps its name.
244	    fn shown_name(&self) -> Option<&str> {
245	        let named_by_badge = ToolKind::of(&self.name) != ToolKind::Other;
246	        (!named_by_badge || self.summary.is_none()).then_some(self.name.as_str())
247	    }
248	
249	    /// Whether the call reads or edits one file, which its summary names.
250	    fn works_on_a_file(&self) -> bool {
251	        matches!(
252	            self.name.as_str(),
253	            "Read" | "Edit" | "MultiEdit" | "Write" | "NotebookRead" | "NotebookEdit"
254	        )
255	    }
256	}
257	
258	#[derive(Clone, Copy, Debug, PartialEq)]
259	enum ToolState {
260	    Running,
261	    Done,
262	    Failed,
263	}
264	
265	impl ToolState {
266	    fn label(self) -> &'static str {
267	        match self {
268	            Self::Running => "running",
269	            Self::Done => "done",
270	            Self::Failed => "failed",
271	        }
272	    }
273	}
274	
275	/// The general type of a tool call, shown as its badge.
276	#[derive(Clone, Copy, Debug, PartialEq)]
277	enum ToolKind {
278	    Read,
279	    Edit,
280	    Command,
281	    Web,
282	    Agent,
283	    Other,
284	}
285	
286	impl ToolKind {
287	    fn of(tool_name: &str) -> Self {
288	        match tool_name {
289	            "Read" | "Glob" | "Grep" | "LS" | "NotebookRead" => Self::Read,
290	            "Edit" | "MultiEdit" | "Write" | "NotebookEdit" => Self::Edit,
291	            "Bash" | "BashOutput" | "KillShell" | "KillBash" => Self::Command,
292	            "WebFetch" | "WebSearch" => Self::Web,
293	            "Task" | "Agent" => Self::Agent,
294	            _ => Self::Other,
295	        }
296	    }
297	
298	    fn label(self) -> &'static str {
299	        match self {
300	            Self::Read => "Files",
301	            Self::Edit => "Edit",
302	            Self::Command => "Command",
303	            Self::Web => "Web",
304	            Self::Agent => "Agent",
305	            Self::Other => "Tool",
306	        }
307	    }
308	
309	    fn icon(self) -> IconName {
310	        match self {
311	            Self::Read => IconName::BookOpen,
312	            Self::Edit => IconName::FilePenLine,
313	            Self::Command => IconName::SquareTerminal,
314	            Self::Web => IconName::Globe,
315	            Self::Agent => IconName::Bot,
316	            Self::Other => IconName::Wrench,
317	        }
318	    }
319	
320	    fn color(self) -> ColorName {
321	        match self {
322	            Self::Read => ColorName::Sky,
323	            Self::Edit => ColorName::Amber,
324	            Self::Command => ColorName::Violet,
325	            Self::Web => ColorName::Teal,
326	            Self::Agent => ColorName::Pink,
327	            Self::Other => ColorName::Gray,
328	        }
329	    }
330	}
331	
332	/// A row of a task's output table.
333	#[derive(Debug, PartialEq)]
334	enum OutputRow<'a> {
335	    /// Reply text; empty while its first words are on their way.
336	    Text(&'a str),
337	    Tool(&'a ToolCall),
338	    Error(&'a str),
339	    /// The harness is still at work, and nothing is known of what comes next.
340	    Pending,
341	}
342	
343	impl OutputRow<'_> {
344	    /// The kind of the row, as a badge in its own colour, or a skeleton while
345	    /// the kind is not yet known.
346	    fn badge(&self) -> AnyElement {
347	        let (tag, icon, label) = match self {
348	            Self::Text(_) => (Tag::secondary(), IconName::MessageSquare, "Reply"),
349	            Self::Tool(call) => {
350	                let kind = ToolKind::of(&call.name);
351	                (Tag::color(kind.color()), kind.icon(), kind.label())
352	            }
353	            Self::Error(_) => (Tag::danger(), IconName::TriangleAlert, "Error"),
